import fs from'node:fs';import{createClient}from'@supabase/supabase-js';import{rowDelta}from'../src/features/panol/panolMovimientos.js';process.loadEnvFile('.env');process.loadEnvFile('.env.backup.local');const db=createClient(process.env.VITE_SUPABASE_URL,process.env.SUPABASE_SERVICE_ROLE_KEY,{auth:{persistSession:false}});async function read(q){const{data,error}=await q;if(error)throw error;return data;}const dir='backups/jl-audio-blanco-93523-20261103';fs.mkdirSync(dir,{recursive:true});const mats=await read(db.from('panol_materiales').select('*').or('descripcion.ilike.%M3-770%,codigo.eq.93523,codigo_barra.eq.699440935234,descripcion.ilike.%93523%').order('id'));const ids=mats.map(x=>x.id);const snaps=await read(db.from('panol_obra_materiales_snapshot').select('*').or('material_id.in.('+ids.join(',')+'),descripcion.ilike.%M3-770%').order('id'));const envios=await read(db.from('panol_envio_items').select('*').or('material_id.in.('+ids.join(',')+'),descripcion.ilike.%M3-770%').order('id'));const reqitems=await read(db.from('purchase_request_items').select('*').or('material_id.in.('+ids.join(',')+'),description.ilike.%M3-770%').order('id'));const obras=await read(db.from('produccion_obras').select('id,codigo,estado').in('id',[...new Set(snaps.map(x=>x.obra_id).filter(Boolean))]));const links=await read(db.from('panol_requisito_productos').select('*').or('requisito_material_id.in.('+ids.join(',')+'),producto_material_id.in.('+ids.join(',')+')'));const before={mats,snaps,envios,reqitems,obras,links};fs.writeFileSync(`${dir}/diagnostico.json`,JSON.stringify(before,null,2));console.log(JSON.stringify({mats:mats.map(x=>({id:x.id,descripcion:x.descripcion,codigo:x.codigo,barcode:x.codigo_barra,unidad:x.unidad_medida,activo:x.activo,req:x.es_requisito,prov:x.proveedor,precio:x.precio_unitario,moneda:x.moneda})),snaps:snaps.map(x=>({id:x.id,material:x.material_id,req:x.requisito_material_id,descripcion:x.descripcion,obra:obras.find(o=>o.id===x.obra_id)?.codigo,cant:x.cantidad,unidad:x.unidad,egresada:x.cantidad_egresada,estado:x.estado,source:x.source,delta:rowDelta(x),sede:x.stock_sede})),envios:envios.map(x=>({id:x.id,mat:x.material_id,snap:x.obra_snapshot_item_id,desc:x.descripcion,cant:x.cantidad,unidad:x.unidad,estado:x.estado})),links}));
